function inside(x,y,poly){let c=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let a=poly[i],b=poly[j];if(((a[1]>y)!==(b[1]>y))&&(x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]))c=!c;}return c;}
function distanceToEdge(x,y,p){let best=1e9;for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy)));best=Math.min(best,Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy));}return best;}
function ground(x,y){return inside(x,y,land)||docks.some(p=>inside(x,y,p))||distanceToEdge(x,y,land)<7;}
function blocked(x,y){return objects.some(o=>inside(x,y,o.foot))||rocks.some(([a,b,r])=>Math.hypot(x-a,y-b)<r+3)||bushes.some(([a,b,r])=>Math.hypot(x-a,y-b)<r);}
function canStand(x,y){return ground(x,y)&&!blocked(x,y)&&!blocked(x-3,y)&&!blocked(x+3,y)&&!blocked(x,y+2);}
function idx(x,y){return Math.max(0,Math.min(ROWS-1,Math.floor(y/STEP)))*COLS+Math.max(0,Math.min(COLS-1,Math.floor(x/STEP)));}
function point(i){return {x:i%COLS*STEP+STEP/2,y:Math.floor(i/COLS)*STEP+STEP/2};}
function neighbours(i,mask=grid){const x=i%COLS,y=Math.floor(i/COLS),a=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;const nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=COLS||ny>=ROWS)continue;const n=ny*COLS+nx;if(!mask[n])continue;if(dx&&dy&&(!mask[y*COLS+nx]||!mask[ny*COLS+x]))continue;a.push(n);}return a;}
function nearest(x,y,mask=reachable){let best=-1,d=Infinity;for(let i=0;i<mask.length;i++)if(mask[i]){const p=point(i),v=(p.x-x)**2+(p.y-y)**2;if(v<d){d=v;best=i;}}return best;}
