function updatePools(dt){if(!$('modal').classList.contains('hidden'))return;for(const a of poolAnimals){if(a.caught||a.escaped||(poolHeld?.type==='animal'&&poolHeld.item===a))continue;a.age+=dt;a.grace=Math.max(0,a.grace-dt);const kind=poolSpecies.find(s=>s.id===a.kind);if(a.age>a.wait&&!a.grace){a.x+=a.dx*kind.speed*dt;a.y+=a.dy*kind.speed*dt;}if(a.age>a.life||a.x<65||a.x>449||a.y<138||a.y>610){a.escaped=true;poolMessage('A little escape into the seaweed. Try another stone.');}}$('poolRefresh').disabled=!(poolStones.every(s=>s.revealed)&&poolAnimals.every(a=>a.caught||a.escaped));}
function drawCreature(g,a,t,scale=1){const kind=poolSpecies.find(s=>s.id===a.kind);g.save();g.translate(Math.round(a.x),Math.round(a.y));g.scale(scale,scale);const move=poolHeld?.item===a||a.age>a.wait,phase=settings.ambient&&move?t*12:0;g.strokeStyle=kind.colour;g.lineWidth=3;g.lineCap='square';if(kind.id==='octopus'){for(let i=0;i<8;i++){const angle=i/8*Math.PI*2,wave=Math.sin(phase+i)*3;g.beginPath();g.moveTo(Math.cos(angle)*5,Math.sin(angle)*4);g.lineTo(Math.round(Math.cos(angle)*13+wave),Math.round(Math.sin(angle)*10));g.lineTo(Math.round(Math.cos(angle)*18),Math.round(Math.sin(angle)*13+wave));g.stroke();}g.fillStyle=kind.colour;g.fillRect(-8,-9,16,16);g.fillRect(-5,-13,10,4);}else{for(let side of [-1,1])for(let j=0;j<4;j++){g.beginPath();g.moveTo(side*7,-5+j*4);g.lineTo(side*13,Math.round(-8+j*5+Math.sin(phase+j)*3));g.lineTo(side*18,Math.round(-6+j*5-Math.sin(phase+j)*3));g.stroke();}g.fillStyle=kind.colour;g.fillRect(-10,-7,20,14);g.fillRect(-14,-13,7,7);g.fillRect(7,-13,7,7);if(kind.id==='hermit'){g.fillStyle='#8c7454';g.fillRect(-10,-12,19,18);g.fillStyle='#d2bc88';g.fillRect(-7,-9,13,12);g.fillStyle='#927a5b';g.fillRect(-4,-6,7,7);}}g.fillStyle='#302f35';g.fillRect(-5,-4,2,3);g.fillRect(3,-4,2,3);g.restore();}
