function normaliseLook(a){for(const [key,max]of [['top',3],['bottom',4],['shoes',4],['hat',4],['facial',4]])a[key]=Number.isInteger(a[key])&&a[key]>=0&&a[key]<max?a[key]:0;a.eyewear=Number.isInteger(a.eyewear)&&a.eyewear>=0&&a.eyewear<3?a.eyewear:a.glasses?2:0;a.glasses=a.eyewear===2;return a;}
function facing(dx,dy,route,actor,previous){const ahead=route[Math.min(4,route.length-1)],vx=ahead?ahead.x-actor.x:dx,vy=ahead?ahead.y-actor.y:dy,front=previous==='up'||previous==='down';if(Math.abs(vy)>(front?.25:.45)*Math.abs(vx))return vy<0?'up':'down';if(Math.abs(vx)>Math.abs(vy)*4||!front)return vx<0?'left':'right';return previous;}
function configRows(){const hats=['None','Cap','Beanie','Sun hat'],facial=['None','Beard','Moustache','Stubble'],tops=[{label:'Teal T-shirt',top:0,outfit:0,pattern:'plain'},{label:'Pink T-shirt',top:0,outfit:5,pattern:'plain'},{label:'Cream shirt',top:1,outfit:2,pattern:'plain'},{label:'Rust shirt',top:1,outfit:1,pattern:'plain'},{label:'Blue jumper',top:2,outfit:3,pattern:'plain'},{label:'Green jumper',top:2,outfit:4,pattern:'plain'}];if(economy.owned.striped)tops.push({label:'Striped shirt',top:1,outfit:0,pattern:'striped'});if(economy.owned.tropical)tops.push({label:'Flower shirt',top:1,outfit:1,pattern:'tropical'});const eyes=[{label:'None',eyewear:0},{label:'Glasses',eyewear:1}];if(economy.owned.sunglasses)eyes.push({label:'Sunglasses',eyewear:2});return [{label:'Hair style',items:['Short','Bob','Long','Curly','Cropped','Swept'],index:appearance.style,set:i=>appearance.style=i},{label:'Hair colour',items:['Brown','Black','Blond','Auburn','Silver','Rose','Slate'],index:appearance.hair,set:i=>appearance.hair=i},{label:'Headwear',items:hats,index:appearance.hat||0,set:i=>appearance.hat=i},{label:'Eyewear',items:eyes.map(i=>i.label),index:Math.max(0,eyes.findIndex(i=>i.eyewear===(appearance.eyewear||(appearance.glasses?2:0)))),set:i=>{appearance.eyewear=eyes[i].eyewear;appearance.glasses=eyes[i].eyewear===2;}},{label:'Facial hair',items:facial,index:appearance.facial||0,set:i=>appearance.facial=i},{label:'Top',items:tops.map(i=>i.label),index:Math.max(0,tops.findIndex(i=>i.top===(appearance.top||0)&&i.outfit===appearance.outfit&&i.pattern===(appearance.pattern||'plain'))),set:i=>Object.assign(appearance,tops[i])},{label:'Bottom',items:['Shorts','Skirt','Trousers','Long skirt'],index:appearance.bottom||0,set:i=>appearance.bottom=i},{label:'Footwear',items:['Barefoot','Sandals','Trainers','Boots'],index:appearance.shoes||0,set:i=>appearance.shoes=i}];}
function swatches(){const left=$('configLeft'),right=$('configRight');left.innerHTML='';right.innerHTML='';for(const row of configRows()){const l=document.createElement('div'),r=document.createElement('div');l.className=r.className='config-row';const back=document.createElement('button'),next=document.createElement('button'),label=document.createElement('small'),value=document.createElement('small');back.textContent='‹';next.textContent='›';back.setAttribute('aria-label','Previous '+row.label.toLowerCase());next.setAttribute('aria-label','Next '+row.label.toLowerCase());back.onclick=()=>{row.set((row.index+row.items.length-1)%row.items.length);swatches();};next.onclick=()=>{row.set((row.index+1)%row.items.length);swatches();};label.textContent=row.label;value.textContent=row.items[row.index];l.append(back);l.append(label);r.append(next);r.append(value);left.append(l);right.append(r);}$('skinOptions').innerHTML='';palette.skin.forEach((colour,i)=>{const b=document.createElement('button');b.className='swatch'+(appearance.skin===i?' selected':'');b.style.background=colour;b.setAttribute('aria-label','Skin tone '+(i+1));b.onclick=()=>{appearance.skin=i;swatches();};$('skinOptions').append(b);});renderPortrait();}
function renderPortrait(){const g=$('portrait').getContext('2d');g.clearRect(0,0,180,400);g.imageSmoothingEnabled=false;g.fillStyle='#b9ac8755';g.fillRect(35,281,110,8);character(g,90,283,normaliseLook(appearance),'down',0,5.3);}
function boatState(id){const s=boatServices.find(s=>s.id===id),now=absoluteMinute(),c=calendar(),start=480,end=720;if(c.weekday===s.weekday&&c.minute>=start&&c.minute<end)return {active:true,in:0,left:end-c.minute};let ahead=(s.weekday-c.weekday+7)%7;if(ahead===0&&c.minute>=end)ahead=7;return {active:false,in:ahead*DAY+start-c.minute,left:0};}
function islandTime(after=0){return dateText(absoluteMinute()+after);}
function updateBoatBoard(){if(!profile)return;$('coinCount').textContent=economy.coins;$('greeting').textContent=dateText();const services=boatServices.map(s=>({...s,...boatState(s.id)})).sort((a,b)=>a.in-b.in);for(const s of services){const b=$('visit-'+s.id),weekday=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][s.weekday];b.textContent=`${s.name} — ${s.active?'Here now':weekday+' (AM)'}`;b.classList.toggle('boat-here',s.active);b.setAttribute('aria-label',s.active?'Visit '+s.name:s.name+' due '+weekday+' morning');$('boatRows').append(b);}const signature=services.map(s=>s.id+':'+s.active).join();if(signature!==boatSignature){boatSignature=signature;renderLabels();}}
