const itemNames={...Object.fromEntries(Object.entries(foodTypes).map(([k,v])=>[k,v.name])),bait:'Bait',sunglasses:'Sunglasses',striped:'Striped shirt',tropical:'Flower shirt',line:'Stronger line'};
let intro=null,previewDance=0;
const motions=Object.fromEntries(boatServices.map(s=>[s.id,{progress:0,phase:'away'}]));
function packUsed(){return supplyKeys.filter(k=>(economy.stock[k]||0)>0).length;}
function packFits(k,n=1){return (economy.stock[k]||0)+n<=10&&((economy.stock[k]||0)>0||packUsed()<6);}
const persistV5=persist;persist=function(){if(profile)$('globalPack').textContent='Pack '+packUsed()+'/12';persistV5();};
function packCounter(){return `<div class="capacity"><b>Backpack</b><span>${packUsed()} / 12 spaces</span><small>Each space holds up to 20 of one item</small></div>`;}
const loadRoutineV5=loadRoutine;loadRoutine=function(data){loadRoutineV5(data);routine.introPending=data?.introPending===true;routine.chest={items:{},fish:[],creatures:[]};for(const k of supplyKeys){const n=data?.chest?.items?.[k];if(Number.isSafeInteger(n)&&n>0&&n<=100000)routine.chest.items[k]=n;}routine.chest.fish=Array.isArray(data?.chest?.fish)?data.chest.fish.filter(validCatch):[];routine.chest.creatures=Array.isArray(data?.chest?.creatures)?data.chest.creatures.filter(c=>poolSpecies.some(p=>p.id===c.species)&&Number.isFinite(c.size)&&c.size>0&&c.size<100&&typeof c.caughtAt==='string'):[];intro=null;resetMotions();};
const loadV5=load;load=function(data){loadV5(data);for(const k of supplyKeys){const n=data.economy?.stock?.[k];if(Number.isSafeInteger(n)&&n>=0)economy.stock[k]=n;}};
const freshRoutineV5=freshRoutine;freshRoutine=function(){return {...freshRoutineV5(),introPending:false,chest:{items:{},fish:[],creatures:[]}};};
function quarterClock(min=absoluteMinute()){return calendar(Math.floor(min/15)*15).clock;}
const updateLifeV5=updateLifeUI;updateLifeUI=function(){updateLifeV5();$('lifeClock').textContent=quarterClock();$('globalPack').textContent='Pack '+packUsed()+'/12';};
dateText=function(min=absoluteMinute()){const c=calendar(min);return `${c.short} ${c.date.getUTCDate()} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][c.date.getUTCMonth()]} · ${quarterClock(min)}`;};
function resetMotions(){for(const m of Object.values(motions)){m.phase='away';m.progress=0;}}
function scheduledBoat(id){const s=boatServices.find(s=>s.id===id),c=calendar(),start=480,end=720;if(c.weekday===s.weekday&&c.minute>=start&&c.minute<end)return {scheduled:true,in:0,left:end-c.minute};let ahead=(s.weekday-c.weekday+7)%7;if(!ahead&&c.minute>=end)ahead=7;return {scheduled:false,in:ahead*DAY+start-c.minute,left:0};}
boatState=function(id){const state=scheduledBoat(id),m=motions[id];return {...state,active:state.scheduled&&m.phase==='docked',arriving:state.scheduled&&m.phase!=='docked',departing:m.phase==='leaving'};};
function updateBoatMotions(dt){if(!profile||!['game','fishing','house','pools','beach','forage','dock','woods','photo19'].includes(screen)||!$('modal').classList.contains('hidden')||sleeping||intro)return;const candidates=boatServices.filter(s=>!(s.id==='ferry'&&(freeFerry15()||isPine13()))).filter(s=>scheduledBoat(s.id).scheduled?motions[s.id].phase!=='docked':motions[s.id].phase!=='away');const moving=candidates.find(s=>motions[s.id].progress>0&&motions[s.id].progress<1)||candidates[0];let changed=false;for(const s of boatServices){if(!moving||s.id!==moving.id)continue;const m=motions[s.id],due=scheduledBoat(s.id).scheduled,before=m.phase;if(due){if(m.phase==='away'||m.phase==='leaving')m.phase='arriving';m.progress=Math.min(1,m.progress+dt/7);if(m.progress===1)m.phase='docked';}else if(m.phase!=='away'){m.phase='leaving';m.progress=Math.max(0,m.progress-dt/7);if(!m.progress)m.phase='away';}changed ||= before!==m.phase;}if(changed)updateBoatBoard();}
