updateBoatBoard=function(){if(!profile)return;$('coinCount').textContent=economy.coins;$('greeting').textContent=dateText();const services=boatServices.map(s=>({...s,...boatState(s.id)})).sort((a,b)=>a.in-b.in);for(const s of services){const b=$('visit-'+s.id),weekday=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][s.weekday];b.textContent=`${s.name} · ${s.active?'Here now':s.arriving?'Docking…':s.departing?'Sailing away':weekday+' (AM)'}`;b.classList.toggle('boat-here',s.active);b.setAttribute('aria-label',s.active?'Visit '+s.name:s.name+' due '+weekday+' morning');$('boatRows').append(b);}const signature=services.map(s=>s.id+':'+s.active+':'+s.arriving+':'+s.departing).join();if(signature!==boatSignature){boatSignature=signature;renderLabels();}};
