function transferSupply(k,fromChest,all=false){if(!supplyKeys.includes(k))return false;const chest=routine.chest.items,from=fromChest?chest:economy.stock,to=fromChest?economy.stock:chest;let n=all?(from[k]||0):Math.min(1,from[k]||0);if(fromChest){if(!(economy.stock[k]>0)&&packUsed()>=12)return false;n=Math.min(n,Math.max(0,20-(economy.stock[k]||0)));}if(!n)return false;from[k]-=n;to[k]=(to[k]||0)+n;persist();return true;}
