// v0.7 — letters, parcels and a few island companions.
const requestKinds={fish:{title:'A fish for supper',from:'Bruce, across the sound',need:'One mackerel measuring at least 25 cm',coins:35,decor:'shell'},crab:{title:'A tiny tide-pool visitor',from:'The island nature club',need:'One hermit crab, any size',coins:45},lost:{title:'My missing brass key',from:'Ellis, ferry crew',need:'A lost brass key last seen on the beach',coins:55,decor:'plant'}};
const beachTypes={shell:{name:'Scallop shell',metal:false,value:3},glass:{name:'Sea glass',metal:false,value:4},wood:{name:'Driftwood',metal:false,value:2},pebble:{name:'Smooth pebble',metal:false,value:1},coin:{name:'Old coin',metal:true,value:6},cap:{name:'Bottle cap',metal:true,value:1},key:{name:'Lost brass key',metal:true,value:0}};
function freshPost(){return {letters:[],requests:[],serial:0,lastFerry:-1,started:false};}
function initV7(){routine.post||=freshPost();routine.beachBucket||=[];routine.beachRecords||={};routine.chest.beach||=[];routine.decor||={plant:false,rug:false,shell:false};}
const freshRoutineV6=freshRoutine;freshRoutine=function(){const r=freshRoutineV6();r.post=freshPost();r.beachBucket=[];r.beachRecords={};r.chest.beach=[];r.decor={plant:false,rug:false,shell:false};return r;};
function validBeach(c){return c&&beachTypes[c.type]&&typeof c.foundAt==='string';}
const loadRoutineV6=loadRoutine;loadRoutine=function(d){loadRoutineV6(d);initV7();const p=d?.post;if(p&&typeof p==='object'){routine.post.serial=Number.isSafeInteger(p.serial)&&p.serial>=0?p.serial:0;routine.post.lastFerry=Number.isInteger(p.lastFerry)?p.lastFerry:-1;routine.post.started=p.started===true;routine.post.requests=Array.isArray(p.requests)?p.requests.filter(r=>r&&requestKinds[r.kind]&&/^req-\d+$/.test(r.id)&&['finding','ready','shipped','replied','complete','missed'].includes(r.status)&&Number.isFinite(r.deadline)).slice(-80).map(r=>({...r,parcel:r.parcel&&((r.kind==='fish'&&validCatch(r.parcel))||(r.kind==='crab'&&r.parcel.species==='hermit'&&Number.isFinite(r.parcel.size))||(r.kind==='lost'&&validBeach(r.parcel)))?r.parcel:null})):[];routine.post.letters=Array.isArray(p.letters)?p.letters.filter(l=>l&&typeof l.id==='string'&&/^(bulletin-storm|(request|thanks)-req-\d+)$/.test(l.id)&&['bulletin','request','thanks'].includes(l.kind)).slice(-100).map(l=>({id:l.id,kind:l.kind,requestId:l.requestId,read:l.read===true,claimed:l.claimed===true})):[];}for(const r of routine.post.requests){if(r.status==='ready'&&(!r.parcel||!Number.isFinite(r.pickupAt))){r.status='finding';r.parcel=null;}if(r.status==='shipped'&&!Number.isFinite(r.returnAt)){r.returnAt=nextCollection()+7*DAY-240;}}routine.beachBucket=Array.isArray(d?.beachBucket)?d.beachBucket.filter(validBeach):[];routine.chest.beach=Array.isArray(d?.chest?.beach)?d.chest.beach.filter(validBeach):[];for(const k of Object.keys(beachTypes))routine.beachRecords[k]=Number.isSafeInteger(d?.beachRecords?.[k])?Math.max(0,d.beachRecords[k]):0;for(const k of ['plant','rug','shell'])routine.decor[k]=d?.decor?.[k]===true;routine.beachPatch=validPatch(d?.beachPatch)?d.beachPatch:null;if(!routine.post.started&&!routine.introPending)startPost();};
const loadV6=load;load=function(d){loadV6(d);for(const k of ['plant','rug','shell'])economy.owned[k]=d.economy?.owned?.[k]===true||routine.decor[k]||(economy.stock[k]||0)>0||(routine.chest.items[k]||0)>0;};
function dayLabel(day){const c=calendar(day*DAY+480);return `${c.short} ${c.date.getUTCDate()} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][c.date.getUTCMonth()]}`;}
function nextCollection(min=absoluteMinute()){const c=calendar(min);let ahead=(1-c.weekday+7)%7;if(!ahead&&c.minute>=720)ahead=7;return (c.day+ahead)*DAY+720;}
function addLetter(kind,requestId=''){const id=kind+'-'+(requestId||'storm');if(!routine.post.letters.some(l=>l.id===id))routine.post.letters.push({id,kind,requestId,read:false,claimed:false});}
function issueRequest(kind){if(routine.post.requests.filter(r=>['finding','ready','shipped'].includes(r.status)).length>=2)return null;const id='req-'+(++routine.post.serial),deadline=nextCollection()+7*DAY;const r={id,kind,status:'finding',deadline,parcel:null,pickupAt:0,returnAt:0};routine.post.requests.push(r);addLetter('request',id);return r;}
function startPost(){initV7();if(routine.post.started)return;routine.post.started=true;if(calendar().weekday===1&&calendar().minute<720)routine.post.lastFerry=calendar().day;addLetter('bulletin');issueRequest('fish');}
const finishArrivalV6=finishArrival;finishArrival=function(){finishArrivalV6();startPost();routine.post.lastFerry=calendar().day;persist();notify('There is a letter waiting in the mailbox by the dock.');};
function tickPost(){if(!profile||!routine.post||intro)return;startPost();const now=absoluteMinute(),c=calendar(),post=routine.post;let changed=false;const ferry=boatState('ferry');if(ferry.active&&post.lastFerry!==c.day){post.lastFerry=c.day;if(post.requests.length&&post.requests.filter(r=>['finding','ready','shipped'].includes(r.status)).length<2){const kind=['fish','crab','lost'][post.serial%3];issueRequest(kind);}postFlash={until:clock+6,kind:'mail'};notify('The ferry has brought the post.');changed=true;}
 for(const r of post.requests){if(r.status==='ready'&&r.parcel&&now>=r.pickupAt){r.status='shipped';r.parcel=null;r.returnAt=r.pickupAt+7*DAY-240;postFlash={until:clock+7,kind:'parcel'};notify('Your parcel is aboard. A reply is due with the following ferry.');changed=true;}if(r.status==='finding'&&now>r.deadline){r.status='missed';changed=true;}if(r.status==='shipped'&&now>=r.returnAt&&(now>=r.returnAt+240||ferry.active)){r.status='replied';addLetter('thanks',r.id);postFlash={until:clock+6,kind:'mail'};notify('A thank-you letter is waiting in your mailbox.');changed=true;}}if(changed)persist();}
function unreadPost(){return routine.post?.letters.filter(l=>!l.read||l.kind==='thanks'&&!l.claimed).length||0;}
function requestStatus(r){return {finding:'Finding items',ready:'Ready to send',shipped:'Collected · reply due',replied:'Thank-you waiting',complete:'Completed',missed:'Collection date passed'}[r.status];}
function letterTitle(l){if(l.kind==='bulletin')return 'Island bulletin · services returning';const r=routine.post.requests.find(r=>r.id===l.requestId);return l.kind==='thanks'?'A little thank you':r?requestKinds[r.kind].title:'An old island letter';}
function openMailbox(){modal('Post by the landing',`<p class="mini-note">Letters arrive with the Monday ferry. Read letters stay here.</p><div class="letter-list">${routine.post.letters.slice().reverse().sort((a,b)=>Number(b.kind==='bulletin'&&!b.read)-Number(a.kind==='bulletin'&&!a.read)).map(l=>`<button id="letter-${l.id}" class="letter-card"><span>${!l.read?'✉':'♡'}</span><b>${letterTitle(l)}</b><small>${l.kind==='thanks'&&!l.claimed?'Reward enclosed':!l.read?'Unread':'Read'}</small></button>`).join('')||'<p>No post yet. The ferry will bring news.</p>'}</div>`,'ISLAND POST');for(const l of routine.post.letters)$('letter-'+l.id).onclick=()=>readLetter(l.id);}
function readLetter(id){const l=routine.post.letters.find(l=>l.id===id);if(!l)return;l.read=true;const r=routine.post.requests.find(r=>r.id===l.requestId),k=r&&requestKinds[r.kind];let body='';if(l.kind==='bulletin')body='<p class="letter-dateline">LOCAL FERRY BULLETIN</p><h3>Ferry services gradually returning</h3><p>Following the recent storm, Home Island’s landing is the first local dock cleared for use. Other island routes remain suspended while repairs continue.</p><p>Supply boats and postal deliveries can now resume. Further route announcements will arrive by post.</p><p>There is no rush. Settle back in, and keep an eye on your mailbox.</p>';else if(r&&l.kind==='request')body=`<p class="letter-dateline">From ${k.from}</p><p>${r.kind==='fish'?'Would you spare a mackerel for supper? Anything 25 cm or longer would be lovely.':r.kind==='crab'?'We’re looking for a hermit crab for a short observation at our nature club. Any size will do.':'I dropped my brass key somewhere along your beach before the storm. A metal detector should help you find it beneath the sand.'}</p><div class="request-detail"><b>${k.need}</b><p>Last collection: ${dayLabel(calendar(r.deadline).day)} · before noon</p><p>Thank-you: ${k.coins} coins${k.decor?' + '+(k.decor==='shell'?'a shell ornament':'a small plant'):''}</p></div><p>Pop it in the mailbox Outbox. The ferry will collect it, and I’ll send a reply with the following ferry. No worries if you can’t manage it.</p><button class="action" id="letterRequest">View request</button>`;else if(r)body=`<p class="letter-dateline">From ${k.from}</p><p>${r.kind==='lost'?'My key is back! Thank you for taking the time to search the beach.':r.kind==='crab'?'Our tiny visitor arrived safely. Thank you for helping the nature club.':'The fish arrived safely and made a lovely supper. Thank you for thinking of us.'}</p><p>I’ve enclosed ${k.coins} coins${k.decor?' and a little something for your house':''}. Hope you’re settling in.</p><button class="action gold" id="claimPost" ${l.claimed?'disabled':''}>${l.claimed?'Gift received':'Receive enclosed gift'}</button>`;modal(letterTitle(l),body+'<button class="action" id="backMailbox">Back to letters</button>','A LETTER FOR YOU');if($('letterRequest'))$('letterRequest').onclick=()=>openRequest(r.id);if($('claimPost'))$('claimPost').onclick=()=>{claimLetter(l.id);readLetter(l.id);};$('backMailbox').onclick=openMailbox;persist();}
function claimLetter(id){const l=routine.post.letters.find(l=>l.id===id),r=l&&routine.post.requests.find(r=>r.id===l.requestId);if(!l||l.kind!=='thanks'||l.claimed||!r||r.status!=='replied')return false;const k=requestKinds[r.kind];l.claimed=true;r.status='complete';economy.coins+=k.coins;if(k.decor){if(!economy.owned[k.decor]){economy.owned[k.decor]=true;routine.chest.items[k.decor]=(routine.chest.items[k.decor]||0)+1;}else economy.coins+=10;}persist();updateBoatBoard();return true;}
function openRequests(){modal('Small favours, at your own pace',routine.post.requests.slice().reverse().map(r=>`<button class="request-card" id="request-${r.id}"><small>${requestStatus(r)}</small><b>${requestKinds[r.kind].title}</b><span>${requestKinds[r.kind].need}</span><em>${r.status==='shipped'?'Reply: '+dayLabel(calendar(r.returnAt).day):'Last collection: '+dayLabel(calendar(r.deadline).day)}</em></button>`).join('')||'<p>New requests will arrive by post.</p>','REQUEST JOURNAL');for(const r of routine.post.requests)$('request-'+r.id).onclick=()=>openRequest(r.id);}
