function brushSand(x,y,dy=1){if(x<38||x>474||y<214||y>610)return false;const dig=beachTool==='spade',marked=beachItems.find(i=>i.marked&&!i.collected&&Math.hypot(x-i.x,y-i.y)<45);if(dig&&!marked)return false;const radius=dig?22:19,limit=dig?10:4;for(let gy=Math.floor((y-radius)/SAND);gy<=Math.ceil((y+radius)/SAND);gy++)for(let gx=Math.floor((x-radius)/SAND);gx<=Math.ceil((x+radius)/SAND);gx++){if(gx<0||gy<0||gx>=BC||gy>=BR)continue;const xx=gx*SAND+SAND/2,yy=gy*SAND+SAND/2;if(Math.hypot(xx-x,(yy-y)*.7)>radius)continue;if(dig&&Math.hypot(xx-marked.x,yy-marked.y)>37)continue;const id=gy*BC+gx;sandDepth[id]=Math.max(sandDepth[id],Math.min(limit,sandDepth[id]+1));}const pileY=Math.round(y+(dy<0?-1:1)*(radius+3)),nearPile=sandPiles.find(p=>Math.hypot(p.x-x,p.y-pileY)<12);if(nearPile){nearPile.x=Math.round(x);nearPile.y=pileY;}else sandPiles.push({x:Math.round(x),y:pileY,w:radius});if(sandPiles.length>100)sandPiles.shift();for(const i of beachItems)if(!i.collected&&!i.announced&&exposure(i)>=1){i.announced=true;beachMessage(beachTypes[i.type].name+'! Drag it into the bucket.');}return true;}
function detectorAt(x,y){let nearest=null,d=Infinity;for(const i of beachItems)if(!i.collected&&beachTypes[i.type].metal){const dist=Math.hypot(i.x-x,i.y-y);if(dist<d){nearest=i;d=dist;}}detectorStrength=Math.max(0,100-d);if(nearest&&d<27&&!nearest.marked){nearest.marked=true;beachMessage('Metal found. Switch to the spade and dig inside the circle.');if(settings.vibration&&navigator.vibrate)try{navigator.vibrate(35);}catch(e){}}if(detectorStrength>8&&clock-lastDetectorBeep>1.05-detectorStrength/120){lastDetectorBeep=clock;detectorBeep(detectorStrength);}updateBeachCount();return nearest;}
function detectorBeep(strength){if(!settings.sound||!biteAudio||biteAudio.state!=='running')return;try{const o=biteAudio.createOscillator(),g=biteAudio.createGain(),t=biteAudio.currentTime;o.type='sine';o.frequency.setValueAtTime(380+strength*5,t);g.gain.setValueAtTime(.025,t);g.gain.exponentialRampToValueAtTime(.0001,t+.1);o.connect(g);g.connect(fxOutput());o.start(t);o.stop(t+.12);}catch(e){}}
function beachPoint(e){const r=beachCanvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H};}
function strokeBeach(p,prev){beachCursor=p;if(beachTool==='detector'){detectorAt(p.x,p.y);return;}const length=prev?Math.hypot(p.x-prev.x,p.y-prev.y):0,n=Math.max(1,Math.ceil(length/8));for(let i=1;i<=n;i++){const u=i/n;brushSand(prev?prev.x+(p.x-prev.x)*u:p.x,prev?prev.y+(p.y-prev.y)*u:p.y,prev?p.y-prev.y:1);}}
