function mailboxTabs(active){return `<nav class="mail-tabs" aria-label="Mailbox"><button id="mailInbox" aria-pressed="${active==='inbox'}">${uiIcon('mail')} Inbox${unreadPost()?` <b>${unreadPost()}</b>`:''}</button><button id="mailOutbox" aria-pressed="${active==='outbox'}">${uiIcon('bag')} Outbox</button></nav>`;}
