function openWoods(){modal('A quiet place among the trees',`<div class="shrine-scene">${objectIcon11('shrine')}</div><div class="shrine-sockets" aria-label="Five empty places">${['○','△','□','☾','◇'].map((symbol,i)=>`<button id="shrine-${i}" aria-label="Inspect empty ${['round','triangular','square','crescent','diamond'][i]} recess">${symbol}</button>`).join('')}</div><p id="shrineThought" class="shrine-thought">Five empty places. Each marked with a different symbol.</p><button id="woodsWood" class="action">${objectIcon11('logs')} Gather wood</button>`,'THE WOODLAND SHRINE');routine.shrineSeen=true;persist();const lines=['A wave worn into the stone. Something once rested here.','Fine lines branch out like pine needles.','The outline looks a little like a distant tower.','A pale crescent, smooth beneath your fingers.','A pattern like reeds reflected in still water.'];for(let i=0;i<5;i++)$('shrine-'+i).onclick=()=>{$('shrineThought').textContent=lines[i];};$('woodsWood').onclick=openWoodcutting;}
