function materialCount(key){if(key.startsWith('find:')){const type=key.slice(5);return routine.beachBucket.concat(routine.chest.beach).filter(c=>c.type===type).length;}return (economy.stock[key]||0)+(routine.chest.items[key]||0);}
function materialLabel(key){return key.startsWith('find:')?beachTypes[key.slice(5)].name:itemNames[key]||key;}
function materialIcon(key){return key.startsWith('find:')?artIcon(key.slice(5)==='shell'?'scallop':key.slice(5)):foodIcon(key);}
function canSpendMaterials(cost){return Object.entries(cost).every(([key,n])=>Number.isSafeInteger(n)&&n>0&&materialCount(key)>=n);}
function spendMaterials(cost){if(!canSpendMaterials(cost))return false;for(const [key,n]of Object.entries(cost)){let left=n;if(key.startsWith('find:')){for(const arr of [routine.beachBucket,routine.chest.beach])for(let i=arr.length-1;i>=0&&left;i--)if(arr[i].type===key.slice(5)){arr.splice(i,1);left--;}}else{for(const stock of [routine.chest.items,economy.stock]){const take=Math.min(stock[key]||0,left);stock[key]=(stock[key]||0)-take;left-=take;}}}return true;}
